const org = await ctx.db.get("organisation", String(row["organisation_id"] ?? ""));
const orgName = org ? String(org["name"] ?? "an organisation") : "an organisation";
const email = String(row["email"] ?? "").trim().toLowerCase();
if (!email) return;
const emailField = "{{param.email_field}}";
if (emailField) {
  const people = await ctx.db.list("{{param.member_role}}", { limit: 1000 });
  const person = people.find((p) => String(p[emailField] ?? "").trim().toLowerCase() === email);
  if (person) {
    await ctx.db.create("membership", { organisation_id: String(row["organisation_id"]), member_id: String(person["id"]), team_id: row["team_id"] ?? null, role: String(row["role"] ?? "member"), status: "active" });
    await ctx.db.update("invitation", String(row["id"]), { status: "accepted" });
    if (person["user_id"]) await ctx.notify({ title: `You joined ${orgName}`, body: `You were added as ${String(row["role"] ?? "member")}.`, user: String(person["user_id"]) });
    return;
  }
}
await ctx.email({ to: email, subject: `You're invited to join ${orgName}`, body: `You've been invited to join ${orgName} as ${String(row["role"] ?? "member")}.\n\nSign up with this email address (${email}) and you'll be added automatically.` });

const email = String(row["{{param.email_field}}"] ?? "").trim().toLowerCase();
if (!email) return;
const pending = await ctx.db.list("invitation", { filter: { status: "pending" }, limit: 1000 });
for (const inv of pending) {
  if (String(inv["email"] ?? "").trim().toLowerCase() !== email || String(inv["status"]) !== "pending") continue;
  await ctx.db.create("membership", { organisation_id: String(inv["organisation_id"]), member_id: String(row["id"]), team_id: inv["team_id"] ?? null, role: String(inv["role"] ?? "member"), status: "active" });
  await ctx.db.update("invitation", String(inv["id"]), { status: "accepted" });
}
